-- Datos de prueba. Los viajes se generan desde hoy y por 7 días,
-- así la demo siempre tiene viajes en el día actual.

insert into rutas.rutas (nombre, descripcion) values
  ('Ruta Centro',  'Centro de Ocaña hacia la sede El Algodonal'),
  ('Ruta Terminal', 'Terminal de Transportes hacia la sede El Algodonal');

-- Coordenadas de OpenStreetMap (ver migrations/20261030000001_mapa_de_rutas.sql).
insert into rutas.paradas (ruta_id, nombre, orden, latitud, longitud)
select r.id, p.nombre, p.orden, p.lat, p.lng
from rutas.rutas r
join (values
  ('Ruta Centro',   'Parque 29 de Mayo',                 1, 8.235412, -73.353856),
  ('Ruta Centro',   'Hospital Emiro Quintero Cañizares', 2, 8.254306, -73.358398),
  ('Ruta Centro',   'Sede El Algodonal',                 3, 8.235200, -73.322090),
  ('Ruta Terminal', 'Terminal de Transportes',           1, 8.233251, -73.341168),
  ('Ruta Terminal', 'Avenida Circunvalar · La Paz',      2, 8.228629, -73.338167),
  ('Ruta Terminal', 'Sede El Algodonal',                 3, 8.235200, -73.322090)
) as p (ruta, nombre, orden, lat, lng) on p.ruta = r.nombre;

